-- 0. Migration 0009-ийн үүсгэсэн анхны ангиллуудыг (Хүнс / Сав баглаа / Бусад)
--    авч хаяна — production-д эдгээр нь өөр id-тай тул lower(name) unique
--    index дээр мөргөлддөг. Зөвхөн ХЭРЭГЛЭГДЭЭГҮЙ (материал ч, дэд ангилал ч
--    холбогдоогүй) мөрийг л устгах тул дахин ажиллуулахад аюулгүй.
delete from public.material_categories c
  where c.parent_id is null
    and lower(c.name) in ('хүнс', 'сав баглаа', 'бусад')
    and c.id not in ('87cb3c0f-50c3-47eb-bb7e-d4083145870c', '9b2881da-b774-4330-803d-1bf7cf3db283', 'f0528099-92b5-4ab9-bd81-7193f8ca666a', 'bc28e5a9-7d24-4d42-83db-15d032a7db52', 'bc1ae492-50e2-4230-ad9c-326f659e7462', '36676e23-cf98-4732-8048-fe08c4353ac9', '724b5dd2-0aac-4b10-b87a-f762696fce84')
    and not exists (
      select 1 from public.materials m where m.category_id = c.id)
    and not exists (
      select 1 from public.material_categories k where k.parent_id = c.id);

