-- Кодын sequence-ийг одоо байгаа хамгийн том дугаараас цааш нь тавина
-- (шинэ бичлэг давхар код авахаас сэргийлнэ).
select setval('public.customers_code_seq',
              greatest(coalesce(max(substring(code from 5)::int), 0), 1),
              coalesce(max(substring(code from 5)::int), 0) > 0)
  from public.customers where code ~ '^CUS-[0-9]+$';
select setval('public.suppliers_code_seq',
              greatest(coalesce(max(substring(code from 5)::int), 0), 1),
              coalesce(max(substring(code from 5)::int), 0) > 0)
  from public.suppliers where code ~ '^SUP-[0-9]+$';
select setval('public.materials_code_seq',
              greatest(coalesce(max(substring(code from 5)::int), 0), 1),
              coalesce(max(substring(code from 5)::int), 0) > 0)
  from public.materials where code ~ '^MAT-[0-9]+$';
select setval('public.products_code_seq',
              greatest(coalesce(max(substring(code from 5)::int), 0), 1),
              coalesce(max(substring(code from 5)::int), 0) > 0)
  from public.products where code ~ '^PRD-[0-9]+$';
